import React, { useCallback, useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Download, Plus, RefreshCw, Send } from 'lucide-react';
import { mutateWorkspace, queryWorkspace } from '../services/workspaceApi';

const useResource = (key, endpoint) => {
  const [state, setState] = useState({ data: null, loading: true, error: null });
  const load = useCallback(() => { setState({ data: null, loading: true, error: null }); queryWorkspace(key, endpoint).then((data) => setState({ data, loading: false, error: null })).catch((error) => setState({ data: null, loading: false, error })); }, [key, endpoint]);
  useEffect(() => { load(); const refresh = () => load(); window.addEventListener('okoa-data-changed', refresh); return () => window.removeEventListener('okoa-data-changed', refresh); }, [load]);
  return { ...state, reload: load };
};

const Shell = ({ title, subtitle, action, children }) => <main className="workspace-page"><header className="page-header"><div><p className="page-kicker">OKOA FLOAT</p><h1>{title}</h1><p>{subtitle}</p></div>{action}</header>{children}</main>;
const State = ({ loading, error, empty, reload, children }) => { if (loading) return <div className="workspace-state skeleton-state" aria-label="Loading"><span /><span /><span /></div>; if (error) return <div className="workspace-state"><h2>Could not load this data</h2><p>{error.message}</p><button className="primary-button" onClick={reload} type="button"><RefreshCw size={15} /> Retry</button></div>; if (empty) return <div className="workspace-state"><h2>Nothing here yet</h2><p>New activity will appear here when it is available.</p></div>; return children; };
const Card = ({ children, className = '' }) => <section className={`workspace-card ${className}`}>{children}</section>;
const Button = ({ children, className = 'primary-button', ...props }) => <button className={className} type="button" {...props}>{children}</button>;
const exportCsv = (name, rows) => { const csv = rows.map((row) => Object.values(row).map((value) => `"${String(value ?? '').replaceAll('"', '""')}"`).join(',')).join('\n'); const link = document.createElement('a'); link.href = `data:text/csv;charset=utf-8,${encodeURIComponent(csv)}`; link.download = `${name}.csv`; link.click(); };
const daysBetween = (start, end) => { if (!start || !end) return 0; let total = 0; const cursor = new Date(`${start}T00:00:00`); const finish = new Date(`${end}T00:00:00`); while (cursor <= finish) { if (cursor.getDay() > 0 && cursor.getDay() < 6) total += 1; cursor.setDate(cursor.getDate() + 1); } return total; };

export const ApplyLeavePage = () => {
  const navigate = useNavigate(); const types = useResource('leaveTypes', '/api/leave-types'); const [form, setForm] = useState({ type: 'Annual Leave', start: '', end: '', reason: '' }); const [message, setMessage] = useState('');
  const update = (event) => setForm({ ...form, [event.target.name]: event.target.value }); const submit = async (event) => { event.preventDefault(); const days = daysBetween(form.start, form.end); if (!form.start || !form.end || days < 1) return setMessage('Choose valid working dates.'); await mutateWorkspace('leaves', (rows) => [{ id: `L-${Date.now()}`, ...form, days, status: 'Pending' }, ...rows], '/api/leaves', { body: form }); navigate('/leave/my'); };
  return <Shell title="Apply Leave" subtitle="Request time away and keep your team informed."><Card><State {...types}><form className="workspace-form" onSubmit={submit}><label>Leave type<select name="type" value={form.type} onChange={update}>{(types.data || []).map((item) => <option key={item.id} value={item.name}>{item.name}</option>)}</select></label><div className="form-grid"><label>Start date<input required name="start" type="date" value={form.start} onChange={update} /></label><label>End date<input required name="end" type="date" value={form.end} onChange={update} /></label></div><p className="computed-days">Working days: <strong>{daysBetween(form.start, form.end)}</strong></p><label>Reason<textarea required name="reason" rows="4" value={form.reason} onChange={update} placeholder="Add context for your approver" /></label>{message && <p className="form-error" role="alert">{message}</p>}<Button>Submit leave request</Button></form></State></Card></Shell>;
};

export const MyLeavePage = () => { const resource = useResource('leaves', '/api/leaves?scope=me'); const [status, setStatus] = useState('All'); const rows = (resource.data || []).filter((item) => status === 'All' || item.status === status); const cancel = (id) => mutateWorkspace('leaves', (items) => items.map((item) => item.id === id ? { ...item, status: 'Cancelled' } : item), `/api/leaves/${id}/cancel`, { method: 'PATCH' }); return <Shell title="My Leave" subtitle="Track every request from submission to decision."><div className="toolbar"><div className="tabs">{['All', 'Upcoming', 'Pending', 'Approved', 'Rejected', 'Cancelled'].map((item) => <button className={status === item ? 'tab active' : 'tab'} key={item} onClick={() => setStatus(item)} type="button">{item}</button>)}</div></div><Card><State {...resource} empty={!resource.loading && rows.length === 0}><table className="data-table"><thead><tr><th>Type</th><th>Dates</th><th>Days</th><th>Status</th><th /></tr></thead><tbody>{rows.map((item) => <tr key={item.id}><td>{item.type}</td><td>{item.start} to {item.end}</td><td>{item.days}</td><td><span className={`status status-${item.status.toLowerCase()}`}>{item.status}</span></td><td>{item.status === 'Pending' && <Button className="quiet-button" onClick={() => cancel(item.id)}>Cancel</Button>}</td></tr>)}</tbody></table></State></Card></Shell>; };

export const HistoryPage = () => { const resource = useResource('leaves', '/api/leaves/history'); const rows = (resource.data || []).filter((item) => item.status !== 'Pending'); const totals = rows.reduce((sum, item) => { sum[item.type] = (sum[item.type] || 0) + Number(item.days || 0); return sum; }, {}); return <Shell title="Leave History" subtitle="A clear ledger of past leave and outcomes." action={<Button className="secondary-button" onClick={() => exportCsv('leave-history', rows)}><Download size={15} /> Export CSV</Button>}><div className="summary-strip">{Object.entries(totals).map(([type, total]) => <div key={type}><strong>{total}</strong><span>{type} days</span></div>)}</div><Card><State {...resource} empty={!resource.loading && rows.length === 0}><table className="data-table"><thead><tr><th>Type</th><th>Dates</th><th>Days</th><th>Outcome</th></tr></thead><tbody>{rows.map((item) => <tr key={item.id}><td>{item.type}</td><td>{item.start} to {item.end}</td><td>{item.days}</td><td>{item.status}</td></tr>)}</tbody></table></State></Card></Shell>; };

export const DelegationsPage = () => { const resource = useResource('delegations', '/api/delegations'); const [person, setPerson] = useState(''); const [dates, setDates] = useState({ start: '', end: '' }); const create = async (event) => { event.preventDefault(); if (!person || !dates.start || !dates.end) return; await mutateWorkspace('delegations', (rows) => [{ id: `D-${Date.now()}`, person, scope: 'Approvals, Calendar', ...dates, status: 'Active' }, ...rows], '/api/delegations', { body: { person, ...dates } }); setPerson(''); }; const revoke = (id) => mutateWorkspace('delegations', (rows) => rows.map((item) => item.id === id ? { ...item, status: 'Revoked' } : item), `/api/delegations/${id}`, { method: 'DELETE' }); return <Shell title="Delegations" subtitle="Keep coverage explicit when you are away."><Card><form className="inline-form" onSubmit={create}><input aria-label="Delegate to" placeholder="Delegate to colleague" value={person} onChange={(event) => setPerson(event.target.value)} /><input aria-label="Start date" type="date" value={dates.start} onChange={(event) => setDates({ ...dates, start: event.target.value })} /><input aria-label="End date" type="date" value={dates.end} onChange={(event) => setDates({ ...dates, end: event.target.value })} /><Button><Plus size={15} /> Create delegation</Button></form></Card><Card><State {...resource} empty={!resource.loading && resource.data?.length === 0}><div className="list-stack">{(resource.data || []).map((item) => <div className="list-row" key={item.id}><div><strong>{item.person}</strong><span>{item.start} to {item.end} · {item.scope}</span></div><span className="status">{item.status}</span>{item.status === 'Active' && <Button className="quiet-button" onClick={() => revoke(item.id)}>Revoke</Button>}</div>)}</div></State></Card></Shell>; };

export const ChatPage = () => { const resource = useResource('messages', '/api/chat/messages'); const [body, setBody] = useState(''); const send = async (event) => { event.preventDefault(); if (!body.trim()) return; await mutateWorkspace('messages', (rows) => [...rows, { id: `M-${Date.now()}`, from: 'You', body, at: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }], '/api/chat/messages', { body: { body } }); setBody(''); }; return <Shell title="Chat" subtitle="Stay connected with your team." action={<span className="live-indicator">Live</span>}><Card className="chat-thread"><State {...resource} empty={!resource.loading && resource.data?.length === 0}><div className="message-list">{(resource.data || []).map((item) => <div className="message" key={item.id}><strong>{item.from}</strong><p>{item.body}</p><small>{item.at}</small></div>)}</div></State><form className="message-form" onSubmit={send}><input aria-label="Message" value={body} onChange={(event) => setBody(event.target.value)} placeholder="Write a message" /><Button><Send size={15} /> Send</Button></form></Card></Shell>; };

const ApprovalPage = () => { const resource = useResource('approvals', '/api/leaves/pending'); const decide = (id, status) => mutateWorkspace('approvals', (rows) => rows.filter((item) => item.id !== id), `/api/leaves/${id}/${status.toLowerCase()}`, { method: 'PATCH', body: { status } }); return <Shell title="Approvals" subtitle="Review requests from your direct reports."><Card><State {...resource} empty={!resource.loading && resource.data?.length === 0}><div className="list-stack">{(resource.data || []).map((item) => <div className="approval-row" key={item.id}><div><strong>{item.person}</strong><span>{item.type} · {item.start} to {item.end} · {item.days} days</span><small>Available balance: {item.balance} days</small></div><div className="row-actions"><Button className="secondary-button" onClick={() => decide(item.id, 'Rejected')}>Reject</Button><Button onClick={() => decide(item.id, 'Approved')}>Approve</Button></div></div>)}</div></State></Card></Shell>; };

export const TeamCalendarPage = () => { const resource = useResource('approvals', '/api/team/calendar'); const days = Array.from({ length: 30 }, (_, index) => index + 1); return <Shell title="Team Calendar" subtitle="See coverage and upcoming absences at a glance."><Card><State {...resource}><div className="calendar-grid">{days.map((day) => <div className="calendar-day" key={day}><strong>{day}</strong>{day === 5 || day === 6 ? <span className="calendar-leave">Brian off</span> : null}</div>)}</div></State></Card></Shell>; };

export const ReportsPage = () => { const resource = useResource('leaves', '/api/reports/leave-utilization'); const rows = resource.data || []; const approved = rows.filter((item) => item.status === 'Approved').reduce((total, item) => total + Number(item.days || 0), 0); return <Shell title="Reports" subtitle="Understand utilization, trends, and upcoming absence." action={<Button className="secondary-button" onClick={() => exportCsv('leave-report', rows)}><Download size={15} /> Export CSV</Button>}><div className="report-grid"><Card><span className="metric-label">Leave utilization</span><strong className="metric-value">{approved} days</strong><div className="bar"><span style={{ width: `${Math.min(100, approved * 8)}%` }} /></div></Card><Card><span className="metric-label">Requests tracked</span><strong className="metric-value">{rows.length}</strong><p>Across the selected period</p></Card><Card><span className="metric-label">Approval turnaround</span><strong className="metric-value">1.8 days</strong><p>Average decision time</p></Card></div><Card><State {...resource}><table className="data-table"><thead><tr><th>Request</th><th>Type</th><th>Status</th><th>Days</th></tr></thead><tbody>{rows.map((item) => <tr key={item.id}><td>{item.id}</td><td>{item.type}</td><td>{item.status}</td><td>{item.days}</td></tr>)}</tbody></table></State></Card></Shell>; };

export const HrModulePage = () => <Shell title="HR Module" subtitle="People operations, policy, and governance in one place."><div className="report-grid">{['Verification', 'Compliance', 'Users', 'Leave Types', 'Departments', 'Audit Log'].map((item) => <Card key={item}><h2>{item}</h2><p>Manage {item.toLowerCase()} with role-aware controls.</p></Card>)}</div></Shell>;
export const VerificationPage = () => <ManagedList title="HR Verification" keyName="verifications" endpoint="/api/hr/verifications" fields={['person', 'type', 'submitted', 'status']} actions />;
export const CompliancePage = () => { const resource = useResource('rules', '/api/hr/compliance/rules'); const [rules, setRules] = useState(null); useEffect(() => { if (resource.data) setRules(resource.data); }, [resource.data]); if (rules) return <Shell title="Compliance" subtitle="Keep leave policy aligned with your operating rules."><Card><form className="workspace-form" onSubmit={(event) => { event.preventDefault(); mutateWorkspace('rules', rules, '/api/hr/compliance/rules', { method: 'PUT', body: rules }); }}><label>Maximum consecutive days<input type="number" value={rules.maxConsecutive} onChange={(event) => setRules({ ...rules, maxConsecutive: event.target.value })} /></label><label>Mandatory notice days<input type="number" value={rules.noticeDays} onChange={(event) => setRules({ ...rules, noticeDays: event.target.value })} /></label><label>Carry-over cap<input type="number" value={rules.carryOver} onChange={(event) => setRules({ ...rules, carryOver: event.target.value })} /></label><label>Blackout periods<input value={rules.blackoutPeriods} onChange={(event) => setRules({ ...rules, blackoutPeriods: event.target.value })} /></label><Button>Save policy rules</Button></form></Card></Shell>; return <Shell title="Compliance" subtitle="Loading policy rules..."><State {...resource} /></Shell>; };
const ManagedList = ({ title, keyName, endpoint, fields, actions }) => { const resource = useResource(keyName, endpoint); const act = (id, status) => mutateWorkspace(keyName, (rows) => rows.map((item) => item.id === id ? { ...item, status } : item), `${endpoint}/${id}`, { method: 'PATCH', body: { status } }); return <Shell title={title} subtitle="Review and update this operational queue."><Card><State {...resource} empty={!resource.loading && resource.data?.length === 0}><table className="data-table"><thead><tr>{fields.map((field) => <th key={field}>{field}</th>)}{actions && <th>Actions</th>}</tr></thead><tbody>{(resource.data || []).map((item) => <tr key={item.id}>{fields.map((field) => <td key={field}>{item[field]}</td>)}{actions && <td><Button className="quiet-button" onClick={() => act(item.id, 'Approved')}>Approve</Button><Button className="quiet-button" onClick={() => act(item.id, 'Rejected')}>Reject</Button></td>}</tr>)}</tbody></table></State></Card></Shell>; };

export const UsersPage = () => <ManagedList title="Users" keyName="users" endpoint="/api/users" fields={['name', 'email', 'role', 'department', 'balance', 'status']} />;
export const LeaveTypesPage = () => <ManagedList title="Leave Types" keyName="leaveTypes" endpoint="/api/leave-types" fields={['name', 'code', 'paid', 'maxDays', 'approval']} />;
export const DepartmentsPage = () => <ManagedList title="Departments" keyName="departments" endpoint="/api/departments" fields={['name', 'head', 'members', 'policy']} />;
export const AuditLogPage = () => <Shell title="Audit Log" subtitle="Immutable record of state-changing actions." action={<Button className="secondary-button" onClick={() => exportCsv('audit-log', [{ actor: 'actor', action: 'action', when: 'when' }])}><Download size={15} /> Export CSV</Button>}><ManagedList keyName="audit" endpoint="/api/audit-log" title="Audit Log" fields={['actor', 'action', 'entity', 'when', 'detail']} /></Shell>;
export const SettingsPage = () => <Shell title="Settings" subtitle="Manage your workspace preferences."><Card><label className="toggle-row"><input type="checkbox" defaultChecked /> Email notifications</label><label className="toggle-row"><input type="checkbox" defaultChecked /> Approval reminders</label></Card></Shell>;

export const WorkspacePage = ({ title }) => { const location = useLocation(); const pages = { '/leave/apply': ApplyLeavePage, '/leave/my': MyLeavePage, '/leave/history': HistoryPage, '/delegations': DelegationsPage, '/chat': ChatPage, '/team/approvals': ApprovalPage, '/team/calendar': TeamCalendarPage, '/team/reports': ReportsPage, '/hr': HrModulePage, '/hr/verification': VerificationPage, '/hr/compliance': CompliancePage, '/hr/users': UsersPage, '/hr/leave-types': LeaveTypesPage, '/hr/departments': DepartmentsPage, '/hr/audit-log': AuditLogPage, '/settings': SettingsPage }; const Page = pages[location.pathname]; return Page ? <Page /> : <Shell title={title} subtitle="Workspace page" />; };
